package com.huawei.finance.domain.payroll;
import static org.assertj.core.api.Assertions.assertThat; import com.huawei.finance.contracts.model.Enums; import com.huawei.finance.contracts.model.GuardrailCheck; import com.huawei.finance.contracts.model.RiskLevel; import com.huawei.finance.contracts.model.UnifiedTask; import java.time.Instant; import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
class PayrollDomainAgentTest {@Test void keepsPayrollDisputesOutOfReadOnlyResult(){var agent=new PayrollDomainAgent(principal->new PayrollStatusPort.StatusView("已到账","2026-07-23","示例单位"));var result=agent.execute(task(Map.of("principalRef","opaque")));assertThat(result.status()).isEqualTo(Enums.TaskStatus.SUCCESS);assertThat(result.resultPayload()).containsEntry("payrollStatus","已到账").doesNotContainKey("补发");}@Test void requiresPrincipal(){var agent=new PayrollDomainAgent(principal->null);assertThat(agent.execute(task(Map.of())).status()).isEqualTo(Enums.TaskStatus.NEED_USER);}private static UnifiedTask task(Map<String,Object> p){return new UnifiedTask("t","trace",Enums.TaskSource.FAST_PATH,"查工资","cap.payroll.status.query",p,RiskLevel.R0,Map.of(),GuardrailCheck.passed(),"idem",List.of(),Instant.now().plusSeconds(5));}}
